{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Naloxone itself is described as having poor oral bioavailability in humans, directly supporting a sub-20% F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Naltrexone, the closest analogue sharing the 6-keto and 14-hydroxy morphinan scaffold, had ~5% oral bioavailability in healthy male volunteers due to extensive first-pass hepatic metabolism, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Butorphanol, a related 14-hydroxy morphinan opioid, had absolute oral bioavailability of 5–17% after oral administration in patients, supporting a low-F pattern for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "One naltrexone study reported 60% oral bioavailability in healthy and post-addict volunteers, providing a conflicting high-F data point for the closest analogue, though most other naltrexone records are much lower.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Nalmefene, a 6-methylene analogue, showed absolute oral bioavailability of about 53% with food in healthy subjects, but the C6 modification and different N-substituent limit transfer to the 6-keto N-allyl query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct evidence identifies the query as naloxone with poor oral bioavailability; the closest analogue naltrexone and related 14-hydroxy morphinans are predominantly low (5–20%), while high-F analogues involve C6 or N-substituent modifications that do not transfer. Therefore F < 20% is better supported.",
  "evidence_gaps": [
    "No quantitative absolute F value for naloxone itself is provided; C23 only states poor bioavailability.",
    "Naltrexone literature is conflicting (5–60%), so exact extrapolation from the closest analogue is uncertain.",
    "High-F analogues such as nalmefene and naloxegol differ at C6 or are PEGylated, limiting direct transfer to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

